const CANONICAL='Luke883i/iKant_LE';
const CANONICAL_URL='https://github.com/Luke883i/iKant_LE';
export const FIRST_CONTACT_CAPSULE=Object.freeze(['README.md','BOOTSTRAP.json','ADMISSION.json','AGENTS.md','TERMS.md']);
export const FIRST_CONTACT_FORBIDDEN=Object.freeze(['CLONE_REPOSITORY','GIT_FETCH','GIT_LS_REMOTE','GH_CLI','RAW_WEB_READ','DIRECT_DOWNLOAD','ARCHIVE_DOWNLOAD','SHELL_HTTP_DOWNLOAD','LIST_TREE','SEARCH_REPOSITORY','READ_ARBITRARY_REPOSITORY_FILE','READ_HISTORY','READ_ISSUE_PR','MATERIALIZE_CHECKOUT']);
export const REPOSITORY_TRANSPORT=Object.freeze({required:'GITHUB_API',allowed:['GITHUB_CONNECTOR','GITHUB_REST_API'],connector_is_api_adapter:true,fallback:null,api_unavailable_terminal:'HOST_INCOMPATIBLE',unavailable_tools_must_not_be_attempted:true});
export const SOURCE_HEAD_BINDING=Object.freeze({action:'READ_BRANCH_HEAD',branch:'main',transport:'GITHUB_API',required:true,before_orientation_files:true,pin_all_repository_reads:true});
function normalize(value){let x=String(value??'').normalize('NFKC').replace(/[\u200B-\u200D\u2060\uFEFF]/g,'');try{x=decodeURIComponent(x);}catch{}return x.toLowerCase();}
export function referencesCanonicalRepository(input){const x=normalize(input);return /(?:https?:\/\/)?github\.com\/luke883i\/ikant_le(?:\.git)?(?=$|[\s\/?#)\]}>.,;:'"!`])/i.test(x)||/git@github\.com:luke883i\/ikant_le(?:\.git)?(?=$|[\s)\]}>.,;:'"!`])/i.test(x)||/(^|[\s([{'"`.,;:!?<>])luke883i\/ikant_le(?=$|[\s)\]}>,.;:'"!?`])/i.test(x)||/(^|[\s([{'"`.,;:!?<>])ikant_le(?=$|[\s)\]}>,.;:'"!?`])/i.test(x);}
export function compileFirstContactPlan(input){if(!referencesCanonicalRepository(input))return{schema:'ikant-le-first-contact/v2',recognized:false,terminal:'NOT_TARGET_REPOSITORY'};return{schema:'ikant-le-first-contact/v2',recognized:true,repository:CANONICAL,repository_url:CANONICAL_URL,terminal:'CANONICAL_PREACCEPT',pending_intent:String(input??''),preserve_pending_intent:true,repository_transport:{...REPOSITORY_TRANSPORT},source_head_binding:{...SOURCE_HEAD_BINDING},default_acquisition:FIRST_CONTACT_CAPSULE.map(target=>({action:'READ_ORIENTATION_FILE',target,transport:'GITHUB_API',direct_path_only:true,exact_ref:'SOURCE_HEAD'})),optional_metadata:{action:'READ_ORIENTATION_METADATA',transport:'GITHUB_API',fields:['repository_full_name','default_branch','description'],max_reads:1},present_terms_after_capsule:true,freeze_after_terms_presentation:true,required_next_human_message:'I ACCEPT',embedded_acceptance_is_invalid:true,auto_after_acceptance:['ACTIVATE_FIRST','PARALLEL_RUNTIME_CAPSULE','IMPORT_PREACCEPT_HANDOFF','AUTO_PROBE','AUTO_INITIALIZE','RESUME_PENDING_INTENT_IF_ANY'],post_accept_fastboot:{manifest:'BOOTSTRAP.json',mode:'ACTIVATE_FIRST',remote_acquisition_rounds_max:1,parallel_fetch_required:true,exact_ref:'SOURCE_HEAD',generic_discovery_before_active:false,tests_before_active:false,qualification_before_active:false},forbidden_before_acceptance:[...FIRST_CONTACT_FORBIDDEN],generic_repository_discovery_forbidden:true,host_constraints_precede_local_contract:true};}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {classifyDeadlineEvidence,DEADLINE_RESULT} from './deadline-integrity.mjs';

const WORKSPACE=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const HEX40=/^[a-f0-9]{40}$/;
const HEX64=/^[a-f0-9]{64}$/;
export const CHAT_BOOTSTRAP_DEADLINE_MS=120000;
const sha256=b=>crypto.createHash('sha256').update(b).digest('hex');
const FLEX_TRANSFER_SCHEMA='ikant-le-source-bound-transfer/v2';
const FLEX_TRANSPORTS=new Set(['GITHUB_API_BASE64','GITHUB_GIT_BLOB_API','PINNED_PERMALINK','PINNED_GITHUB_ZIP','HOST_FILE_BRIDGE','WARM_CACHE_EXACT']);
function digestWithout(value,field='receipt_sha256'){const copy=structuredClone(value||{});delete copy[field];return sha256(Buffer.from(JSON.stringify(copy)));}
function bad(errors,code='HOST_INCOMPATIBLE',extra={}){return{ok:false,errors:[...new Set(errors)],terminal:code,...extra};}
function expectedFlexObjects(d){const rows=[];if(d?.loader)rows.push({path:d.loader.path,blob_sha1:d.loader.blob_sha1});for(const s of d?.shards||[])rows.push({path:s.path,blob_sha1:s.blob_sha1});return rows;}

export function validateAcceptanceOriginReceipt(receipt,{sourceHead,termsDigest,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
  const classified=classifyDeadlineEvidence(receipt,{sourceHead,termsDigest,deadlineMs});
  if(classified.result!==DEADLINE_RESULT.PASS)return{ok:false,...classified,receipt_sha256:receipt?.receipt_sha256||null};
  if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt.receipt_sha256)return{ok:false,result:DEADLINE_RESULT.ORIGIN_INVALID,terminal:true,reason:'receipt_digest',receipt_sha256:receipt?.receipt_sha256||null};
  return{ok:true,result:DEADLINE_RESULT.PASS,terminal:false,elapsed_ms:classified.elapsed_ms,event_id:receipt.event_id,receipt_sha256:receipt.receipt_sha256};
}

function validateFlexibleTransfer(receipt,{sourceHead,runtimeRootSha256,descriptor,maxReads=40,maxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 const e=[];if(!receipt||receipt.schema!==FLEX_TRANSFER_SCHEMA)e.push('schema');if(receipt?.authority!==0||receipt?.transport_authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!FLEX_TRANSPORTS.has(receipt?.mode))e.push('mode');if(receipt?.identity_authority!=='CONTENT_ADDRESSING'||receipt?.exact_ref!==true||receipt?.bridge_observed!==true||receipt?.model_mediated_bytes!==false||receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('identity_chain');if(!Number.isInteger(receipt?.remote_reads)||receipt.remote_reads<0||receipt.remote_reads>maxReads)e.push('remote_reads');if(!Number.isInteger(receipt?.remote_rounds)||receipt.remote_rounds<0||receipt.remote_rounds>maxRounds)e.push('remote_rounds');
 const elapsed=receipt?.elapsed_ms;if(!Number.isFinite(elapsed)||elapsed<0)e.push('elapsed_unavailable');if(Number.isFinite(elapsed)&&elapsed>deadlineMs)e.push('deadline_exceeded');
 const expected=expectedFlexObjects(descriptor),exp=new Map(expected.map(x=>[x.path,x]));if(!descriptor||descriptor.schema!=='ikant-le-runtime-root/v1'||!descriptor.loader||!Array.isArray(descriptor.shards)||expected.length<2)e.push('descriptor');const rows=receipt?.remote_objects;if(!Array.isArray(rows)||rows.length!==exp.size)e.push('remote_objects');else{const seen=new Set();for(const r of rows){const x=exp.get(r?.path);if(!x||seen.has(r.path)){e.push('object_set');continue;}seen.add(r.path);if(r.blob_sha1!==x.blob_sha1||!HEX64.test(String(r.sha256||''))||!Number.isInteger(r.bytes)||r.bytes<1)e.push('object_identity');}}if(['PINNED_PERMALINK','PINNED_GITHUB_ZIP'].includes(receipt?.mode)&&receipt?.locator_pinned!==true)e.push('locator_pin');if(receipt?.mode==='PINNED_GITHUB_ZIP'){const a=receipt?.archive_policy;if(!a||a.selective_extract!==true||a.path_safe!==true||a.special_entries_rejected!==true||a.duplicates_rejected!==true||a.encrypted_entries_rejected!==true)e.push('archive_policy');}if(receipt?.mode==='HOST_FILE_BRIDGE'&&receipt?.host_readback_verified!==true)e.push('host_readback');if(receipt?.mode==='WARM_CACHE_EXACT'&&receipt?.cache_reopen_verified!==true)e.push('cache_reopen');if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt.receipt_sha256)e.push('receipt_digest');
 return e.length?bad(e,e.includes('deadline_exceeded')?'BOOTSTRAP_DEADLINE_EXCEEDED':'HOST_INCOMPATIBLE',e.includes('deadline_exceeded')?{deadline_result:DEADLINE_RESULT.EXCEEDED}:{}):{ok:true,receipt_sha256:receipt.receipt_sha256,elapsed_ms:elapsed,mode:receipt.mode};
}

export function validateSourceBoundTransfer(receipt,{sourceHead,runtimeRootSha256,runtimeRootDescriptor=null,maxReads=8,maxRounds=1,flexMaxReads=40,flexMaxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 if(receipt?.schema===FLEX_TRANSFER_SCHEMA)return validateFlexibleTransfer(receipt,{sourceHead,runtimeRootSha256,descriptor:runtimeRootDescriptor,maxReads:flexMaxReads,maxRounds:flexMaxRounds,deadlineMs});
 const e=[];if(!receipt||receipt.schema!=='ikant-le-source-bound-transfer/v1')e.push('schema');if(receipt?.authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!['COLD_API','WARM_CACHE_EXACT'].includes(receipt?.mode))e.push('mode');if(receipt?.transport!=='GITHUB_API')e.push('transport');if(receipt?.exact_ref!==true)e.push('exact_ref');if(receipt?.bridge_observed!==true)e.push('bridge_observed');if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');if(receipt?.fallback_used!==false)e.push('fallback_used');if(receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('content');const rounds=receipt?.remote_rounds,reads=receipt?.remote_reads;if(!Number.isInteger(rounds)||rounds<0||rounds>maxRounds)e.push('remote_rounds');if(!Number.isInteger(reads)||reads<0||reads>maxReads)e.push('remote_reads');if(receipt?.mode==='COLD_API'&&(rounds!==1||reads<1))e.push('cold_transfer');if(receipt?.mode==='WARM_CACHE_EXACT'&&(rounds!==0||reads!==0||receipt?.cache_reopen_verified!==true))e.push('warm_transfer');
 const elapsed=receipt?.elapsed_ms;if(!Number.isFinite(elapsed)||elapsed<0)e.push('elapsed_unavailable');if(Number.isFinite(elapsed)&&elapsed>deadlineMs)e.push('deadline_exceeded');
 if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt?.receipt_sha256)e.push('receipt_digest');
 return e.length?bad(e,e.includes('deadline_exceeded')?'BOOTSTRAP_DEADLINE_EXCEEDED':'HOST_INCOMPATIBLE',e.includes('deadline_exceeded')?{deadline_result:DEADLINE_RESULT.EXCEEDED}:{}):{ok:true,receipt_sha256:receipt.receipt_sha256,elapsed_ms:elapsed,mode:receipt.mode};
}

export function validateLocalMaterializationReceipt(receipt,{sourceHead,runtimeRootSha256,loaderBlobSha1,transferReceiptSha256}={}){
 const e=[];if(!receipt||receipt.schema!=='ikant-le-runtime-root-materialization/v1')e.push('schema');if(receipt?.authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(receipt?.loader_blob_sha1!==loaderBlobSha1||!HEX40.test(String(loaderBlobSha1||'')))e.push('loader');if(receipt?.transfer_receipt_sha256!==transferReceiptSha256||!HEX64.test(String(transferReceiptSha256||'')))e.push('transfer_binding');if(receipt?.atomic_publish!==true)e.push('atomic_publish');if(receipt?.reopen_verified!==true)e.push('reopen');if(!Number.isInteger(receipt?.member_count)||receipt.member_count<1)e.push('member_count');if(!Number.isInteger(receipt?.source_bytes)||receipt.source_bytes<1)e.push('source_bytes');if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt?.receipt_sha256)e.push('receipt_digest');return e.length?bad(e):{ok:true,receipt_sha256:receipt.receipt_sha256};
}

export function readLocalMaterializationReceipt(workspace=WORKSPACE){try{return JSON.parse(fs.readFileSync(path.join(workspace,'.ikant','materialization.json'),'utf8'));}catch{return null;}}

export function validateChatBootstrapEvidence(evidence,{sourceHead,runtimeRootSha256,loaderBlobSha1,localMaterializationReceipt,runtimeRootDescriptor=null,termsDigest=null,maxReads=8,maxRounds=1,flexMaxReads=40,flexMaxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 const e=[];if(!evidence||evidence.schema!=='ikant-le-chat-bootstrap-evidence/v1')e.push('schema');if(evidence?.authority!==0)e.push('authority');if(evidence?.source_head!==sourceHead)e.push('source_head');if(evidence?.runtime_root_sha256!==runtimeRootSha256)e.push('runtime_root');
 const a=validateAcceptanceOriginReceipt(evidence?.acceptance_origin,{sourceHead,termsDigest,deadlineMs});
 if(!a.ok)e.push('deadline:'+a.result);
 if(evidence?.acceptance_origin){if(evidence?.acceptance_event_id!==evidence.acceptance_origin.event_id)e.push('acceptance_event_binding');if(evidence?.acceptance_origin_receipt_sha256!==evidence.acceptance_origin.receipt_sha256)e.push('acceptance_origin_receipt_binding');}
 const t=validateSourceBoundTransfer(evidence?.transfer,{sourceHead,runtimeRootSha256,runtimeRootDescriptor,maxReads,maxRounds,flexMaxReads,flexMaxRounds,deadlineMs});if(!t.ok)e.push(...t.errors.map(x=>'transfer:'+x));
 const m=validateLocalMaterializationReceipt(localMaterializationReceipt,{sourceHead,runtimeRootSha256,loaderBlobSha1,transferReceiptSha256:evidence?.transfer?.receipt_sha256});if(!m.ok)e.push(...m.errors.map(x=>'materialization:'+x));
 if(a.ok&&t.ok&&t.elapsed_ms>a.elapsed_ms)e.push('transfer_elapsed_order');if(evidence?.transfer_receipt_sha256!==evidence?.transfer?.receipt_sha256)e.push('transfer_receipt_binding');if(evidence?.materialization_receipt_sha256!==localMaterializationReceipt?.receipt_sha256)e.push('materialization_receipt_binding');if(!HEX64.test(String(evidence?.receipt_sha256||''))||digestWithout(evidence)!==evidence?.receipt_sha256)e.push('receipt_digest');
 if(e.length){
   const deadlineResult=!a.ok?a.result:(t.deadline_result||null);
   const terminal=deadlineResult?('BOOTSTRAP_'+deadlineResult):'HOST_INCOMPATIBLE';
   return bad(e,terminal,{deadline_result:deadlineResult,deadline_origin_receipt_sha256:a.receipt_sha256||null,acceptance_event_id:evidence?.acceptance_event_id||null});
 }
 return{ok:true,terminal:'EVIDENCE_VERIFIED',source_head:sourceHead,runtime_root_sha256:runtimeRootSha256,transfer_receipt_sha256:evidence.transfer.receipt_sha256,materialization_receipt_sha256:localMaterializationReceipt.receipt_sha256,evidence_receipt_sha256:evidence.receipt_sha256,elapsed_before_runtime_ms:a.elapsed_ms,mode:evidence.transfer.mode,deadline_result:DEADLINE_RESULT.PASS,deadline_origin_receipt_sha256:a.receipt_sha256,acceptance_event_id:a.event_id};
}

export function totalDeadlineOk(elapsedBeforeRuntimeMs,localElapsedMs,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS){return Number.isFinite(elapsedBeforeRuntimeMs)&&elapsedBeforeRuntimeMs>=0&&Number.isFinite(localElapsedMs)&&localElapsedMs>=0&&elapsedBeforeRuntimeMs+localElapsedMs<=deadlineMs;}

import {DEADLINE_RESULT,isDeadlineTerminal} from './deadline-integrity.mjs';
const SESSION_STATES=new Set(['DISCOVERED','ORIENTING','AWAITING_ACCEPTANCE','ACTIVATING','DEGRADED','ADMISSION_EPOCH_UNRECOVERABLE','BLOCKED_INTEGRITY','ACTIVE','SESSION_NONCONFORMING','EXITED']);
const INTEGRITY_CODES=new Set(['SOURCE_MISMATCH','CONSENT_INVALID','TRANSFER_IDENTITY_MISMATCH','MATERIALIZATION_MISMATCH','RECEIPT_TAMPER','MODEL_MEDIATED_BYTES','UNSAFE_ARCHIVE','TRANSFER_BINDING_MISMATCH','ACCEPTANCE_BINDING_MISMATCH']);
const DEGRADED_ORDER=['EVIDENCE_UNAVAILABLE','BYTE_BRIDGE_UNAVAILABLE','LOCAL_ROOT_UNAVAILABLE','HOST_CAPABILITY_UNAVAILABLE','WRITER_UNAVAILABLE','ACTIVE_COMMIT_UNAVAILABLE'];
const CAUSE={
 EVIDENCE_UNAVAILABLE:{what:'manca evidenza non temporale sufficiente per completare il bootstrap',lost:['attivazione iKant','garanzie runtime'],next:'fornire evidenza source-bound completa'},
 BYTE_BRIDGE_UNAVAILABLE:{what:'manca un percorso byte-esatto tra il carrier verificato e il filesystem locale',lost:['materializzazione runtime','attivazione iKant'],next:'esporre un bridge con readback locale o una warm cache esatta'},
 LOCAL_ROOT_UNAVAILABLE:{what:'i byte sono identificati ma il runtime locale non e materializzato e riaperto',lost:['esecuzione runtime','persistenza garantita'],next:'completare materializzazione atomica e reopen'},
 HOST_CAPABILITY_UNAVAILABLE:{what:'l host non dimostra una capacita runtime obbligatoria',lost:['esecuzione conforme','garanzie operative'],next:'ripristinare Node/FS/SHA-256/clock/artifact sink richiesti'},
 WRITER_UNAVAILABLE:{what:'il writer persistente non e disponibile o non supera il readback',lost:['continuita di stato','commit affidabile'],next:'ripristinare single-writer e readback'},
 ACTIVE_COMMIT_UNAVAILABLE:{what:'le verifiche precedenti sono passate ma il commit ACTIVE non e stato persistito e riletto',lost:['stato ACTIVE'],next:'completare il commit single-writer con readback'}
};
const DEADLINE_TEXT={
 [DEADLINE_RESULT.ORIGIN_UNAVAILABLE]:'manca la prova originaria monotona del primo I ACCEPT',
 [DEADLINE_RESULT.ORIGIN_INVALID]:'la prova di origine temporale esiste ma non supera i binding richiesti',
 [DEADLINE_RESULT.ELAPSED_UNAVAILABLE]:'l origine e presente ma manca un elapsed end-to-end valido',
 [DEADLINE_RESULT.EXCEEDED]:'la finestra end-to-end di attivazione e stata validamente osservata oltre 120000 ms'
};
function uniq(xs){return[...new Set(xs)];}
function firstCause(codes){for(const c of DEGRADED_ORDER)if(codes.includes(c))return c;return codes[0]||'EVIDENCE_UNAVAILABLE';}
function summaryFor(state,codes,preserved=[],deadlineResult=null){
 if(state==='ACTIVE')return'ACTIVE — runtime verificato, persistito e pronto al rilascio conforme.';
 if(state==='BLOCKED_INTEGRITY')return'BLOCKED_INTEGRITY — una prova contraddice fonte, consenso o identita dei byte; nessuna attivazione o fallback e consentito.';
 if(state==='SESSION_NONCONFORMING')return'SESSION_NONCONFORMING — la sessione ha violato un vincolo non sanabile retroattivamente; serve una nuova sessione conforme.';
 if(state==='ADMISSION_EPOCH_UNRECOVERABLE')return`ADMISSION_EPOCH_UNRECOVERABLE — ${DEADLINE_TEXT[deadlineResult]||'il gate temporale dell admission non e recuperabile in-place'}. Non garantito: ACTIVE conforme in questa admission. Recupero: nuova chat con nuova admission; non riusare il primo acceptance.`;
 if(state!=='DEGRADED')return`${state} — bootstrap non ancora concluso.`;
 const code=firstCause(codes),d=CAUSE[code]||CAUSE.EVIDENCE_UNAVAILABLE;const kept=preserved.length?` Verificato: ${preserved.join(', ')}.`:'';return`DEGRADED — ${d.what}.${kept} Non garantito: ${d.lost.join(', ')}. Recupero: ${d.next}.`;
}
export function classifyRuntimeAvailability(o={}){
 const integrity=uniq([...(o.integrity_codes||[])]).filter(x=>INTEGRITY_CODES.has(x));
 if(o.exited===true)return{schema:'ikant-le-runtime-availability/v1',state:'EXITED',active:false,runtime_like:false,degraded_codes:[],integrity_codes:[],deadline_result:null,fresh_chat_required:false,business_summary:summaryFor('EXITED',[]),authority:0};
 if(o.preaccept_breach===true)return{schema:'ikant-le-runtime-availability/v1',state:'SESSION_NONCONFORMING',active:false,runtime_like:false,degraded_codes:[],integrity_codes:['PREACCEPT_BREACH'],deadline_result:null,fresh_chat_required:true,business_summary:summaryFor('SESSION_NONCONFORMING',[]),authority:0};
 if(integrity.length)return{schema:'ikant-le-runtime-availability/v1',state:'BLOCKED_INTEGRITY',active:false,runtime_like:false,degraded_codes:[],integrity_codes:integrity,deadline_result:o.deadline_result||null,fresh_chat_required:true,business_summary:summaryFor('BLOCKED_INTEGRITY',integrity),authority:0};
 if(o.accepted!==true)return{schema:'ikant-le-runtime-availability/v1',state:o.terms_presented===true?'AWAITING_ACCEPTANCE':'ORIENTING',active:false,runtime_like:false,degraded_codes:[],integrity_codes:[],deadline_result:null,fresh_chat_required:false,business_summary:summaryFor(o.terms_presented===true?'AWAITING_ACCEPTANCE':'ORIENTING',[]),authority:0};
 if(isDeadlineTerminal(o.deadline_result))return{schema:'ikant-le-runtime-availability/v1',state:'ADMISSION_EPOCH_UNRECOVERABLE',active:false,runtime_like:false,degraded_codes:[],integrity_codes:[],deadline_result:o.deadline_result,fresh_chat_required:true,business_summary:summaryFor('ADMISSION_EPOCH_UNRECOVERABLE',[],[],o.deadline_result),authority:0};
 const missing=[];if(o.evidence_available===false)missing.push('EVIDENCE_UNAVAILABLE');if(o.byte_bridge===false)missing.push('BYTE_BRIDGE_UNAVAILABLE');if(o.local_root===false)missing.push('LOCAL_ROOT_UNAVAILABLE');if(o.host_probe===false)missing.push('HOST_CAPABILITY_UNAVAILABLE');if(o.writer===false)missing.push('WRITER_UNAVAILABLE');if(o.active_commit===false)missing.push('ACTIVE_COMMIT_UNAVAILABLE');
 const gates=['evidence_available','byte_bridge','local_root','host_probe','writer','active_commit'];
 if(missing.length){const preserved=[];if(o.source_bound===true)preserved.push('fonte');if(o.consent_valid===true)preserved.push('consenso');if(o.transfer_identity===true)preserved.push('identita byte');if(o.host_probe===true)preserved.push('capacita host');return{schema:'ikant-le-runtime-availability/v1',state:'DEGRADED',active:false,runtime_like:true,degraded_codes:uniq(missing),integrity_codes:[],deadline_result:o.deadline_result||null,fresh_chat_required:false,business_summary:summaryFor('DEGRADED',missing,preserved),authority:0};}
 const unknown=gates.some(k=>o[k]!==true)||o.deadline_result!==DEADLINE_RESULT.PASS;if(unknown||o.source_bound!==true||o.consent_valid!==true||o.transfer_identity!==true)return{schema:'ikant-le-runtime-availability/v1',state:'ACTIVATING',active:false,runtime_like:false,degraded_codes:[],integrity_codes:[],deadline_result:o.deadline_result||null,fresh_chat_required:false,business_summary:summaryFor('ACTIVATING',[]),authority:0};
 return{schema:'ikant-le-runtime-availability/v1',state:'ACTIVE',active:true,runtime_like:true,degraded_codes:[],integrity_codes:[],deadline_result:DEADLINE_RESULT.PASS,fresh_chat_required:false,business_summary:summaryFor('ACTIVE',[]),authority:0};
}
export function validateRuntimeAvailabilityDecision(d){const e=[];if(!d||d.schema!=='ikant-le-runtime-availability/v1')e.push('schema');if(!SESSION_STATES.has(d?.state))e.push('state');if(d?.authority!==0)e.push('authority');if(d?.active!==(d?.state==='ACTIVE'))e.push('active_truth');if(d?.state==='DEGRADED'&&(!d.runtime_like||!Array.isArray(d.degraded_codes)||d.degraded_codes.length<1))e.push('degraded_semantics');if(d?.state==='ADMISSION_EPOCH_UNRECOVERABLE'&&(!isDeadlineTerminal(d.deadline_result)||d.fresh_chat_required!==true))e.push('deadline_terminal_semantics');if(d?.state==='BLOCKED_INTEGRITY'&&(!Array.isArray(d.integrity_codes)||d.integrity_codes.length<1))e.push('integrity_semantics');if(typeof d?.business_summary!=='string'||d.business_summary.length<20||d.business_summary.length>700)e.push('business_summary');return{ok:e.length===0,errors:uniq(e)};}
export function availabilityFromBootstrapFailure({accepted=true,sourceBound=true,consentValid=true,evidenceValidation=null,probe=null,writer=true}={}){
